<script setup lang="ts">
import { ref, computed } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import PageShell from '../../components/PageShell.vue'
import { money } from '../../domain'
import { listOrders,mockPay,cancelOrder,confirmOrder,submitReview,applyAftersale } from '../../services/orders'
import type { ApiOrder } from '../../api/types'
import { mediaUrl } from '../../api/client'
import { notify,requireLogin,confirmDemo,detail } from '../../navigation'
import { demo,validateSession } from '../../store'
const rows=ref<ApiOrder[]>([]),tab=ref('待付款'),error=ref(''),busy=ref(false),loading=ref(false)
const states:Record<string,string>={PENDING_PAYMENT:'待付款',PENDING_ARRANGEMENT:'待派单',PENDING_ACCEPTANCE:'待陪玩确认',ACCEPTED:'已接单',IN_SERVICE:'服务中',PENDING_CONFIRMATION:'待验收',COMPLETED:'已完成',CANCELLED:'已取消'}
const slotLabel:Record<string,string>={morning:'上午',afternoon:'下午',evening:'晚上'}
const list=computed(()=>rows.value.filter(o=>states[o.status]===tab.value))
const keys:Record<string,string>={}
const reviewDialog=ref(false),reviewOrder=ref<ApiOrder|null>(null),reviewRating=ref(5),reviewContent=ref('')
const aftersaleDialog=ref(false),aftersaleOrder=ref<ApiOrder|null>(null),aftersaleAmount=ref<number>(0),aftersaleReason=ref('')
function canAftersale(o:ApiOrder):boolean{
  if(o.status==='IN_SERVICE'||o.status==='PENDING_CONFIRMATION')return true
  if(o.status==='COMPLETED'&&o.aftersale_deadline){return new Date(o.aftersale_deadline).getTime()>=Date.now()}
  return false
}
async function refresh(){loading.value=true;error.value='';try{await validateSession();if(demo.loggedIn)rows.value=await listOrders();else rows.value=[]}catch(e){error.value=(e as Error).message;rows.value=[]}finally{loading.value=false}}
async function act(order:ApiOrder,kind:'pay'|'cancel'|'confirm'){if(busy.value||!await confirmDemo(kind==='pay'?'模拟付款':kind==='confirm'?'确认验收':'取消订单','将更新服务端订单，不涉及真实扣款。'))return;busy.value=true;const identity=kind+'-'+order.id;const key=keys[identity] ||= identity+'-'+Date.now();try{const updated=kind==='pay'?await mockPay(order.id,key):kind==='confirm'?await confirmOrder(order.id,key):await cancelOrder(order.id,key);rows.value=rows.value.map(o=>o.id===updated.id?updated:o);delete keys[identity];tab.value=states[updated.status]}catch(e){notify((e as Error).message)}finally{busy.value=false}}
function openReview(o:ApiOrder){reviewOrder.value=o;reviewRating.value=5;reviewContent.value='';reviewDialog.value=true}
async function saveReview(){const o=reviewOrder.value;if(!o)return;if(busy.value)return;busy.value=true;const identity='review-'+o.id;const key=keys[identity] ||= identity+'-'+Date.now();try{const r=await submitReview(o.id,key,reviewRating.value,reviewContent.value.trim());rows.value=rows.value.map(x=>x.id===o.id?{...x,review:r}:x);delete keys[identity];reviewDialog.value=false;notify('评价成功')}catch(e){notify((e as Error).message)}finally{busy.value=false}}
function openAftersale(o:ApiOrder){aftersaleOrder.value=o;aftersaleAmount.value=o.total_amount_cents-(o.refunded_amount_cents||0)-(o.reserved_refund_cents||0);aftersaleReason.value='';aftersaleDialog.value=true}
async function saveAftersale(){const o=aftersaleOrder.value;if(!o)return;if(busy.value)return;const amt=Math.floor(Number(aftersaleAmount.value)||0);if(amt<=0){notify('退款金额须大于0');return}busy.value=true;const identity='aftersale-'+o.id;const key=keys[identity] ||= identity+'-'+Date.now();try{await applyAftersale(o.id,key,amt,aftersaleReason.value.trim());delete keys[identity];aftersaleDialog.value=false;notify('售后申请已提交，等待审核')}catch(e){notify((e as Error).message)}finally{busy.value=false}}
onLoad(options=>{tab.value=options?.tab||'待付款'});onShow(()=>{void refresh()})
</script>
<template><PageShell title="我的订单" backable><view class="body"><scroll-view scroll-x><view class="pills"><button v-for="t in ['待付款','待派单','待陪玩确认','已接单','服务中','待验收','已完成','已取消']" :key="t" class="ui-btn pill" :class="{active:tab===t}" @click="tab=t">{{t}}</button></view></scroll-view><view class="demo-note">模拟订单；付款后由运营派单、陪玩接单服务。已完成订单可评价。</view><button v-if="!demo.loggedIn" class="primary" @click="requireLogin('orders')">请先登录</button><view v-else-if="loading" class="empty">加载中…</view><view v-else-if="error" class="empty">{{error}}<button @click="refresh">重试</button></view><view v-else><view v-for="o in list" :key="o.id" class="card order"><text class="small">{{o.order_no}}</text><view class="row gap"><image :src="mediaUrl(o.cover_url_snapshot)" class="cover"/><view><view>{{o.product_title_snapshot}}</view><text class="muted">{{o.game_name_snapshot}} × {{o.quantity}}</text></view></view><view v-if="o.appointment_date" class="tiny muted">预约：{{o.appointment_date}} {{slotLabel[o.appointment_slot||'']||o.appointment_slot}}</view><view>订单金额 ¥{{money(o.total_amount_cents)}}</view><view class="tiny muted">{{o.created_at}} · {{states[o.status]}}</view><view v-if="o.status==='PENDING_ARRANGEMENT'" class="processing"><text>⏳ 订单正在处理中，客服将为您安排陪玩</text></view><view v-if="o.status==='PENDING_PAYMENT'" class="row gap"><button class="secondary" :disabled="busy" @click="act(o,'cancel')">取消订单</button><button class="primary" :disabled="busy" @click="act(o,'pay')">模拟付款</button></view><view v-else-if="o.status==='PENDING_CONFIRMATION'" class="row gap"><button class="primary" :disabled="busy" @click="act(o,'confirm')">确认验收</button></view><view v-else-if="o.status==='COMPLETED'&&!o.review" class="row gap"><button class="primary" :disabled="busy" @click="openReview(o)">评价</button></view><view v-if="o.status==='PENDING_ARRANGEMENT'" class="row gap"><button class="secondary" @click="detail('support')">联系客服</button></view><view v-if="canAftersale(o)" class="row gap"><button class="secondary" :disabled="busy" @click="openAftersale(o)">申请售后</button></view><view v-if="o.review" class="tiny muted">已评价：{{o.review.rating}} 星</view><view v-if="(o.refunded_amount_cents||0)>0" class="tiny muted">已退款 ¥{{money(o.refunded_amount_cents||0)}}</view></view><view v-if="!list.length" class="empty">暂无订单或该功能未开放</view></view></view></PageShell>
<view v-if="reviewDialog" class="mask"><view class="sheet"><view class="sheet-title">评价订单</view><view class="stars"><button v-for="s in 5" :key="s" class="ui-btn star" :class="{on:s<=reviewRating}" @click="reviewRating=s">★</button></view><textarea v-model="reviewContent" class="input" placeholder="说说这次服务体验（可选）" maxlength="2000"/><view class="row gap"><button class="secondary" @click="reviewDialog=false">取消</button><button class="primary" :disabled="busy" @click="saveReview">提交评价</button></view></view></view>
<view v-if="aftersaleDialog" class="mask"><view class="sheet"><view class="sheet-title">申请售后</view><view class="tiny muted" style="margin-bottom:16rpx">可退金额上限 ¥{{money((aftersaleOrder?.total_amount_cents||0)-(aftersaleOrder?.refunded_amount_cents||0)-(aftersaleOrder?.reserved_refund_cents||0))}}</view><view class="field-label">退款金额（分）</view><input v-model.number="aftersaleAmount" type="number" class="input short" placeholder="输入退款金额（分）"/><view class="field-label">申请说明</view><textarea v-model="aftersaleReason" class="input" placeholder="说明售后原因（可选）" maxlength="2000"/><view class="row gap"><button class="secondary" @click="aftersaleDialog=false">取消</button><button class="primary" :disabled="busy" @click="saveAftersale">提交申请</button></view></view></view></template>
<style scoped>.pills{padding:20rpx 0}.order{margin:24rpx 0;overflow-wrap:anywhere}.order .row{margin:20rpx 0}.processing{margin:16rpx 0;padding:20rpx;background:#f7f4fb;border:1rpx solid #e6e0f0;border-radius:16rpx;color:#6b5a8a;font-size:26rpx}.cover{width:130rpx;height:130rpx;border-radius:20rpx}.mask{position:fixed;inset:0;background:rgba(0,0,0,.4);display:flex;align-items:flex-end;z-index:999}.sheet{background:#fff;width:100%;border-radius:24rpx 24rpx 0 0;padding:32rpx;box-sizing:border-box}.sheet-title{font-size:32rpx;font-weight:600;text-align:center;margin-bottom:24rpx}.stars{display:flex;justify-content:center;gap:12rpx;margin-bottom:24rpx}.star{font-size:48rpx;color:#ddd}.star.on{color:#f5a623}.input{width:100%;min-height:160rpx;border:1rpx solid #e6e0f0;border-radius:16rpx;padding:20rpx;margin-bottom:24rpx;box-sizing:border-box}.input.short{min-height:auto;height:80rpx}.field-label{font-size:26rpx;color:#747486;margin-bottom:8rpx}</style>
